class KMFObjectBuilder extends fb.ObjectBuilder {
  final String? _KEY_ID;
  final keyMaterialRole? _ROLE;
  final keyMaterialAlgorithm? _ALGORITHM;
  final keyMaterialEncoding? _ENCODING;
  final List<int>? _KEY_BYTES;
  final int? _VERSION;
  final int? _EXPIRES_AT;

  KMFObjectBuilder({
    String? KEY_ID,
    String? keyId,
    keyMaterialRole? ROLE,
    keyMaterialAlgorithm? ALGORITHM,
    keyMaterialEncoding? ENCODING,
    List<int>? KEY_BYTES,
    List<int>? keyBytes,
    int? VERSION,
    int? EXPIRES_AT,
    int? expiresAt,
  })
      : _KEY_ID = keyId ?? KEY_ID,
        _ROLE = ROLE,
        _ALGORITHM = ALGORITHM,
        _ENCODING = ENCODING,
        _KEY_BYTES = keyBytes ?? KEY_BYTES,
        _VERSION = VERSION,
        _EXPIRES_AT = expiresAt ?? EXPIRES_AT;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? KEY_IDOffset = _KEY_ID == null ? null
        : fbBuilder.writeString(_KEY_ID!);
    final int? KEY_BYTESOffset = _KEY_BYTES == null ? null
        : fbBuilder.writeListUint8(_KEY_BYTES!);
    fbBuilder.startTable(7);
    fbBuilder.addOffset(0, KEY_IDOffset);
    fbBuilder.addInt8(1, _ROLE?.value);
    fbBuilder.addInt8(2, _ALGORITHM?.value);
    fbBuilder.addInt8(3, _ENCODING?.value);
    fbBuilder.addOffset(4, KEY_BYTESOffset);
    fbBuilder.addUint32(5, _VERSION);
    fbBuilder.addUint64(6, _EXPIRES_AT);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
